141	/**
142	 * Convert an on-disk transcript into the app's ChatMessage[] so the existing
143	 * chat UI can render it natively. Mirrors the live-stream handling in useChat,
144	 * but also treats human `user` lines as user bubbles (the live path never sees
145	 * those because the prompt originates locally).
146	 */
147	export function transcriptToMessages(raw: string): ChatMessage[] {
148	  const lines = raw.split('\n').map((l) => l.trim()).filter(Boolean);
149	  const messages: ChatMessage[] = [];
150	  const toolUseLocation = new Map<string, number>();
151	  let currentAssistantIndex: number | null = null;
152	
153	  const ensureAssistant = (timestamp: number): number => {
154	    if (currentAssistantIndex !== null) return currentAssistantIndex;
155	    messages.push({ id: makeId(), timestamp, role: 'assistant', content: [] });
156	    currentAssistantIndex = messages.length - 1;
157	    return currentAssistantIndex;
158	  };
159	
160	  for (const line of lines) {
161	    let o: any;
162	    try {
163	      o = JSON.parse(line);
164	    } catch {
165	      continue;
166	    }
167	    if (!o || typeof o !== 'object') continue;
168	
169	    const ts = Date.parse(o.timestamp) || Date.now();
170	    const type = o.type;
171	    const content = o.message?.content;
172	
173	    if (type === 'user') {
174	      // A human prompt (string, or an array with a text block and no tool_result).
175	      const isToolResult =
176	        Array.isArray(content) && content.some((b: any) => b && b.type === 'tool_result');
177	
178	      if (isToolResult) {
179	        for (const block of content) {
180	          if (!block || block.type !== 'tool_result') continue;
181	          const card: ToolResultCard = {
182	            toolUseId: block.tool_use_id,
183	            toolName: 'Unknown',
184	            content: (block.content ?? null) as JSONValue,
185	            completedAt: ts,
186	          };
187	          const idx = toolUseLocation.get(block.tool_use_id);
188	          if (idx !== undefined) {
189	            const msg = messages[idx];
190	            const updated = msg.content.map((item) => {
191	              if (item.type === 'toolUse' && item.card.toolUseId === block.tool_use_id) {
192	                card.toolName = item.card.toolName;
193	                return { type: 'toolUse', card: { ...item.card, result: card } } as ChatContent;
194	              }
195	              return item;
196	            });
197	            updated.push({ type: 'toolResult', card });
198	            messages[idx] = { ...msg, content: updated };
199	          }
200	        }
201	        continue;
202	      }
203	
204	      let text = '';
205	      if (typeof content === 'string') text = content;
206	      else if (Array.isArray(content)) {
207	        text = content.map(blockText).filter((t): t is string => !!t).join('\n');
208	      }
209	      if (!text.trim()) continue;
210	      // Skip local command/meta noise that Claude records as user lines.
211	      if (text.startsWith('<command-') || text.startsWith('<local-command')) continue;
212	
213	      messages.push({ id: makeId(), timestamp: ts, role: 'user', content: [{ type: 'text', text }] });
214	      currentAssistantIndex = null;
215	      continue;
216	    }
217	
218	    if (type === 'assistant' && Array.isArray(content)) {
219	      const idx = ensureAssistant(ts);
220	      const next: ChatContent[] = [...messages[idx].content];
221	      for (const block of content) {
222	        if (block?.type === 'text' && typeof block.text === 'string') {
223	          if (!block.text) continue;
224	          const last = next[next.length - 1];
225	          if (last && last.type === 'text') {
226	            next[next.length - 1] = { type: 'text', text: last.text + block.text };
227	          } else {
228	            next.push({ type: 'text', text: block.text });
229	          }
230	        } else if (block?.type === 'thinking' && typeof block.thinking === 'string') {
231	          if (!block.thinking) continue;
232	          const last = next[next.length - 1];
233	          if (last && last.type === 'reasoning') {
234	            next[next.length - 1] = { type: 'reasoning', text: last.text + block.thinking };
235	          } else {
236	            next.push({ type: 'reasoning', text: block.thinking });
237	          }
238	        } else if (block?.type === 'tool_use' && block.id && block.name) {
239	          const card: ToolUseCard = {
240	            toolUseId: block.id,
241	            toolName: block.name,
242	            input: (block.input ?? null) as JSONValue,
243	            startedAt: ts,
244	          };
245	          next.push({ type: 'toolUse', card });
246	          toolUseLocation.set(block.id, idx);
247	        }
248	      }
249	      messages[idx] = { ...messages[idx], content: next };
250	      continue;
251	    }
252	
253	    // system / result / summary lines carry no user-visible bubble.
254	  }
255	
256	  return messages;
257	}
258	
259	export async function readClaudeSessionMessages(
260	  spriteName: string,
261	  sessionId: string
262	): Promise<ChatMessage[]> {
263	  const raw = await readSessionRaw(spriteName, sessionId);
264	  return transcriptToMessages(raw);
265	}
