272	        toolName = item.card.toolName;
273	        const result: ToolResultCard = { toolUseId: callId, toolName, content, completedAt: ts };
274	        return { type: 'toolUse', card: { ...item.card, result } } as ChatContent;
275	      }
276	      return item;
277	    });
278	    updated.push({ type: 'toolResult', card: { toolUseId: callId, toolName, content, completedAt: ts } });
279	    messages[idx] = { ...msg, content: updated };
280	  };
281	
282	  const pushToolUse = (idx: number, card: ToolUseCard) => {
283	    messages[idx] = { ...messages[idx], content: [...messages[idx].content, { type: 'toolUse', card }] };
284	    toolUseLocation.set(card.toolUseId, idx);
285	  };
286	
