288	    const next = [...messages[idx].content];
289	    const last = next[next.length - 1];
290	    if (last && last.type === 'text') {
291	      next[next.length - 1] = { type: 'text', text: `${last.text}\n${text}` };
292	    } else {
293	      next.push({ type: 'text', text });
294	    }
295	    messages[idx] = { ...messages[idx], content: next };
296	  };
