314	        const text = typeof p.message === 'string' ? p.message : '';
315	        if (!text.trim()) break;
316	        messages.push({ id: makeId(), timestamp: ts, role: 'user', content: [{ type: 'text', text }] });
317	        currentAssistantIndex = null;
318	        break;
319	      }
320	      case 'event_msg:agent_message': {
321	        const text = typeof p.message === 'string' ? p.message : '';
322	        if (!text.trim()) break;
323	        appendAssistantText(ensureAssistant(ts), text);
324	        break;
325	      }
326	      case 'response_item:function_call': {
327	        const callId = p.call_id ?? p.id;
328	        if (!callId) break;
329	        const card: ToolUseCard = {
330	          toolUseId: callId,
331	          toolName: 'Bash',
332	          input: { command: commandFromArgs(p.arguments) },
333	          startedAt: ts,
334	        };
335	        pushToolUse(ensureAssistant(ts), card);
336	        break;
337	      }
338	      case 'response_item:function_call_output': {
339	        if (p.call_id) attachResult(p.call_id, (p.output ?? null) as JSONValue, ts);
340	        break;
341	      }
342	      case 'response_item:custom_tool_call': {
343	        const callId = p.call_id ?? p.id;
344	        if (!callId) break;
345	        const isPatch = p.name === 'apply_patch';
346	        const card: ToolUseCard = {
347	          toolUseId: callId,
348	          toolName: isPatch ? 'Edit' : typeof p.name === 'string' ? p.name : 'Tool',
349	          input: isPatch
350	            ? { file_path: patchFirstFile(p.input) ?? 'patch', patch: p.input }
351	            : { input: p.input },
352	          startedAt: ts,
353	        };
354	        pushToolUse(ensureAssistant(ts), card);
355	        break;
356	      }
357	      case 'response_item:custom_tool_call_output': {
358	        if (p.call_id) attachResult(p.call_id, (p.output ?? null) as JSONValue, ts);
359	        break;
360	      }
361	      case 'response_item:web_search_call': {
362	        const id = p.id ?? p.call_id ?? `web-${makeId()}`;
363	        const query = p.action && typeof p.action.query === 'string' ? p.action.query : '';
364	        const idx = ensureAssistant(ts);
365	        const result: ToolResultCard = { toolUseId: id, toolName: 'WebSearch', content: null, completedAt: ts };
366	        pushToolUse(idx, {
367	          toolUseId: id,
368	          toolName: 'WebSearch',
369	          input: { query },
370	          startedAt: ts,
371	          result,
372	        });
373	        break;
374	      }
375	    }
376	  }
377	
378	  return messages;
379	}
380	
381	export async function readCodexSessionMessages(
382	  spriteName: string,
383	  sessionId: string
384	): Promise<ChatMessage[]> {
385	  const raw = await readSessionRaw(spriteName, sessionId);
386	  return codexTranscriptToMessages(raw);
387	}
