1	import { JSONValue, jsonGet, jsonString, jsonPretty } from './claude-events';
2	
3	export type ChatRole = 'user' | 'assistant' | 'system';
4	export type AgentProvider = 'claude' | 'codex';
5	
6	export type ChatStatus = 'idle' | 'connecting' | 'streaming' | 'reconnecting' | 'error';
7	
8	export interface ChatMessage {
9	  id: string;
10	  timestamp: number;
11	  role: ChatRole;
12	  content: ChatContent[];
13	  checkpointId?: string;
14	  checkpointComment?: string;
15	}
16	
17	export type ChatContent =
18	  | { type: 'text'; text: string }
19	  | { type: 'reasoning'; text: string }
20	  | { type: 'toolUse'; card: ToolUseCard }
21	  | { type: 'toolResult'; card: ToolResultCard }
22	  | { type: 'error'; message: string };
23	
24	export interface ToolUseCard {
25	  toolUseId: string;
26	  toolName: string;
27	  input: JSONValue;
28	  startedAt: number;
29	  result?: ToolResultCard;
30	}
31	
32	export interface ToolResultCard {
33	  toolUseId: string;
34	  toolName: string;
35	  content: JSONValue;
36	  completedAt: number;
37	}
38	
39	export function toolUseSummary(card: ToolUseCard): string {
40	  const input = card.input;
41	  switch (card.toolName) {
42	    case 'Bash':
43	      return jsonString(jsonGet(input, 'command')) ?? 'bash command';
44	    case 'Read':
45	      return jsonString(jsonGet(input, 'file_path')) ?? 'read file';
46	    case 'Write':
47	      return jsonString(jsonGet(input, 'file_path')) ?? 'write file';
48	    case 'Edit':
49	      return jsonString(jsonGet(input, 'file_path')) ?? 'edit file';
50	    case 'Glob':
51	      return jsonString(jsonGet(input, 'pattern')) ?? 'glob search';
52	    case 'Grep':
