1	import AsyncStorage from '@react-native-async-storage/async-storage';
2	import { AgentProvider, ChatMessage } from '@/models/chat';
3	import { Database, getDatabase } from './database';
4	
5	/**
6	 * Repository layer for the chat domain.
7	 *
8	 * Replaces the old AsyncStorage `loadChatList`/`saveChatList`/`loadChatMessages`
9	 * calls with a typed, row-oriented API backed by SQLite. Each chat is its own
10	 * row, so a single chat can be updated atomically without rewriting a whole
11	 * JSON list — and queries like "all chats with an active run" become trivial.
12	 *
13	 * On first launch, existing AsyncStorage data (`sprite_chats_*` / `chat_meta_*`)
14	 * is imported once, then SQLite is the only read path.
15	 */
16	
17	// MARK: - Types
18	
19	export interface PersistedChat {
20	  id: string;
21	  spriteName: string;
22	  chatNumber: number;
23	  customName?: string;
24	  provider: AgentProvider;
25	  claudeSessionId?: string;
26	  codexSessionId?: string;
27	  currentServiceName?: string;
28	  workingDirectory: string;
29	  createdAt: number;
30	  lastUsed: number;
31	  isClosed: boolean;
32	  firstMessagePreview?: string;
33	  lastSessionComplete: boolean;
34	  processedEventUUIDs: string[];
35	  activeRun?: ActiveChatRun;
36	}
37	
38	export interface ActiveChatRun {
39	  execSessionId: string;
40	  taskName: string;
41	  provider: AgentProvider;
42	  transport?: 'exec' | 'codexAppServer';
43	  userMessageId: string;
44	  assistantMessageId: string;
45	  workingDirectory: string;
46	  startedAt: number;
47	}
48	
49	// MARK: - Normalization (defensive load-time sanitization)
50	
51	function normalizeProvider(value: unknown): AgentProvider {
52	  return value === 'codex' ? 'codex' : 'claude';
53	}
54	
55	export function normalizePersistedChat(value: unknown): PersistedChat {
56	  const raw = (value ?? {}) as Partial<PersistedChat> & Record<string, unknown>;
57	  return {
58	    id: String(raw.id ?? ''),
59	    spriteName: String(raw.spriteName ?? ''),
60	    chatNumber: Number(raw.chatNumber ?? 1),
61	    customName: typeof raw.customName === 'string' ? raw.customName : undefined,
62	    provider: normalizeProvider(raw.provider),
63	    claudeSessionId: typeof raw.claudeSessionId === 'string' ? raw.claudeSessionId : undefined,
64	    codexSessionId: typeof raw.codexSessionId === 'string' ? raw.codexSessionId : undefined,
65	    currentServiceName:
66	      typeof raw.currentServiceName === 'string' ? raw.currentServiceName : undefined,
67	    workingDirectory: String(raw.workingDirectory ?? ''),
68	    createdAt: Number(raw.createdAt ?? Date.now()),
69	    lastUsed: Number(raw.lastUsed ?? Date.now()),
70	    isClosed: Boolean(raw.isClosed),
71	    firstMessagePreview:
72	      typeof raw.firstMessagePreview === 'string' ? raw.firstMessagePreview : undefined,
73	    lastSessionComplete: raw.lastSessionComplete !== false,
74	    processedEventUUIDs: Array.isArray(raw.processedEventUUIDs)
75	      ? raw.processedEventUUIDs.filter((x): x is string => typeof x === 'string')
76	      : [],
77	    activeRun: normalizeActiveRun(raw.activeRun),
78	  };
79	}
80	
81	function normalizeActiveRun(value: unknown): ActiveChatRun | undefined {
82	  if (!value || typeof value !== 'object') return undefined;
83	  const raw = value as Partial<ActiveChatRun> & Record<string, unknown>;
84	  if (
85	    typeof raw.execSessionId !== 'string' ||
86	    typeof raw.taskName !== 'string' ||
87	    typeof raw.userMessageId !== 'string' ||
88	    typeof raw.assistantMessageId !== 'string'
89	  ) {
90	    return undefined;
91	  }
92	  return {
93	    execSessionId: raw.execSessionId,
94	    taskName: raw.taskName,
95	    provider: normalizeProvider(raw.provider),
96	    transport: raw.transport === 'codexAppServer' ? 'codexAppServer' : 'exec',
97	    userMessageId: raw.userMessageId,
98	    assistantMessageId: raw.assistantMessageId,
99	    workingDirectory: typeof raw.workingDirectory === 'string' ? raw.workingDirectory : '',
100	    startedAt: Number(raw.startedAt ?? Date.now()),
101	  };
102	}
103	
104	// MARK: - Row <-> object mapping
105	
106	interface ChatRow {
107	  id: string;
108	  sprite_name: string;
109	  chat_number: number;
110	  provider: string;
111	  custom_name: string | null;
112	  claude_session_id: string | null;
113	  codex_session_id: string | null;
114	  current_service_name: string | null;
115	  working_directory: string;
116	  created_at: number;
117	  last_used: number;
118	  is_closed: number;
119	  first_message_preview: string | null;
120	  last_session_complete: number;
121	  processed_event_uuids: string;
122	}
123	
124	interface ActiveRunRow {
125	  chat_id: string;
126	  exec_session_id: string;
127	  task_name: string;
128	  provider: string;
129	  transport: string;
130	  user_message_id: string;
131	  assistant_message_id: string;
132	  working_directory: string;
133	  started_at: number;
134	}
135	
136	function rowToActiveRun(row: ActiveRunRow): ActiveChatRun {
137	  return {
138	    execSessionId: row.exec_session_id,
139	    taskName: row.task_name,
140	    provider: normalizeProvider(row.provider),
141	    transport: row.transport === 'codexAppServer' ? 'codexAppServer' : 'exec',
142	    userMessageId: row.user_message_id,
143	    assistantMessageId: row.assistant_message_id,
144	    workingDirectory: row.working_directory,
145	    startedAt: row.started_at,
146	  };
147	}
148	
149	function rowToChat(row: ChatRow, activeRun?: ActiveChatRun): PersistedChat {
150	  return {
151	    id: row.id,
152	    spriteName: row.sprite_name,
153	    chatNumber: row.chat_number,
154	    provider: normalizeProvider(row.provider),
155	    customName: row.custom_name ?? undefined,
156	    claudeSessionId: row.claude_session_id ?? undefined,
157	    codexSessionId: row.codex_session_id ?? undefined,
158	    currentServiceName: row.current_service_name ?? undefined,
159	    workingDirectory: row.working_directory,
160	    createdAt: row.created_at,
161	    lastUsed: row.last_used,
162	    isClosed: Boolean(row.is_closed),
163	    firstMessagePreview: row.first_message_preview ?? undefined,
164	    lastSessionComplete: Boolean(row.last_session_complete),
165	    processedEventUUIDs: safeParseStringArray(row.processed_event_uuids),
166	    activeRun,
167	  };
168	}
169	
170	function safeParseStringArray(raw: string): string[] {
171	  try {
172	    const parsed = JSON.parse(raw);
173	    return Array.isArray(parsed) ? parsed.filter((x): x is string => typeof x === 'string') : [];
174	  } catch {
175	    return [];
176	  }
177	}
178	
179	// MARK: - Low-level writers (operate on a live db/txn handle, no migration guard)
180	
181	const CHAT_UPSERT_SQL = `
182	INSERT INTO chats (
183	  id, sprite_name, chat_number, provider, custom_name, claude_session_id,
184	  codex_session_id, current_service_name, working_directory, created_at,
185	  last_used, is_closed, first_message_preview, last_session_complete,
186	  processed_event_uuids
187	) VALUES (?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?)
188	ON CONFLICT(id) DO UPDATE SET
189	  sprite_name = excluded.sprite_name,
190	  chat_number = excluded.chat_number,
191	  provider = excluded.provider,
192	  custom_name = excluded.custom_name,
193	  claude_session_id = excluded.claude_session_id,
194	  codex_session_id = excluded.codex_session_id,
195	  current_service_name = excluded.current_service_name,
196	  working_directory = excluded.working_directory,
197	  created_at = excluded.created_at,
198	  last_used = excluded.last_used,
199	  is_closed = excluded.is_closed,
200	  first_message_preview = excluded.first_message_preview,
201	  last_session_complete = excluded.last_session_complete,
202	  processed_event_uuids = excluded.processed_event_uuids
203	`;
204	
205	function chatParams(chat: PersistedChat) {
206	  return [
207	    chat.id,
208	    chat.spriteName,
209	    chat.chatNumber,
210	    chat.provider,
211	    chat.customName ?? null,
212	    chat.claudeSessionId ?? null,
213	    chat.codexSessionId ?? null,
214	    chat.currentServiceName ?? null,
215	    chat.workingDirectory,
216	    chat.createdAt,
217	    chat.lastUsed,
218	    chat.isClosed ? 1 : 0,
219	    chat.firstMessagePreview ?? null,
220	    chat.lastSessionComplete ? 1 : 0,
221	    JSON.stringify(chat.processedEventUUIDs ?? []),
222	  ];
223	}
224	
225	const ACTIVE_RUN_UPSERT_SQL = `
226	INSERT INTO active_runs (
227	  chat_id, exec_session_id, task_name, provider, transport, user_message_id,
228	  assistant_message_id, working_directory, started_at
229	) VALUES (?, ?, ?, ?, ?, ?, ?, ?, ?)
230	ON CONFLICT(chat_id) DO UPDATE SET
231	  exec_session_id = excluded.exec_session_id,
232	  task_name = excluded.task_name,
233	  provider = excluded.provider,
234	  transport = excluded.transport,
235	  user_message_id = excluded.user_message_id,
236	  assistant_message_id = excluded.assistant_message_id,
237	  working_directory = excluded.working_directory,
238	  started_at = excluded.started_at
239	`;
240	
241	function activeRunParams(chatId: string, run: ActiveChatRun) {
242	  return [
243	    chatId,
244	    run.execSessionId,
245	    run.taskName,
246	    run.provider,
247	    run.transport ?? 'exec',
248	    run.userMessageId,
249	    run.assistantMessageId,
250	    run.workingDirectory,
251	    run.startedAt,
252	  ];
253	}
254	
255	async function writeChat(db: Database, chat: PersistedChat): Promise<void> {
256	  await db.runAsync(CHAT_UPSERT_SQL, ...chatParams(chat));
257	  if (chat.activeRun) {
258	    await db.runAsync(ACTIVE_RUN_UPSERT_SQL, ...activeRunParams(chat.id, chat.activeRun));
259	  } else {
260	    await db.runAsync('DELETE FROM active_runs WHERE chat_id = ?', chat.id);
261	  }
262	}
263	
264	async function writeMessages(
265	  db: Database,
266	  chatId: string,
267	  messages: ChatMessage[]
268	): Promise<void> {
269	  await db.runAsync('DELETE FROM chat_messages WHERE chat_id = ?', chatId);
270	  if (messages.length === 0) return;
271	  for (let seq = 0; seq < messages.length; seq++) {
272	    await db.runAsync(
273	      'INSERT INTO chat_messages (chat_id, seq, payload) VALUES (?, ?, ?)',
274	      chatId,
275	      seq,
276	      JSON.stringify(messages[seq])
277	    );
278	  }
279	}
280	
281	// MARK: - AsyncStorage -> SQLite migration (runs once)
282	
283	const ASYNC_CHAT_LIST_PREFIX = 'sprite_chats_';
284	const ASYNC_CHAT_META_PREFIX = 'chat_meta_';
285	const MIGRATION_FLAG_KEY = 'async_storage_imported';
286	
287	let migrationDone = false;
288	
289	async function runAsyncStorageMigration(db: Database): Promise<void> {
290	  const already = await db.getFirstAsync<{ value: string }>(
291	    'SELECT value FROM migration_meta WHERE key = ?',
292	    MIGRATION_FLAG_KEY
293	  );
294	  if (already?.value === '1') return;
295	
296	  await db.withTransactionAsync(async () => {
297	    const keys = await AsyncStorage.getAllKeys();
298	    const chatListKeys = keys.filter(
299	      (k): k is string => typeof k === 'string' && k.startsWith(ASYNC_CHAT_LIST_PREFIX)
300	    );
301	    for (const key of chatListKeys) {
302	      const raw = await AsyncStorage.getItem(key);
303	      if (!raw) continue;
304	      let parsed: unknown;
305	      try {
306	        parsed = JSON.parse(raw);
307	      } catch {
308	        continue;
309	      }
310	      if (!Array.isArray(parsed)) continue;
311	      for (const item of parsed) {
312	        const chat = normalizePersistedChat(item);
313	        if (!chat.id) continue;
314	        await writeChat(db, chat);
315	      }
316	    }
317	
318	    const metaKeys = keys.filter(
319	      (k): k is string => typeof k === 'string' && k.startsWith(ASYNC_CHAT_META_PREFIX)
320	    );
321	    for (const key of metaKeys) {
322	      const chatId = key.slice(ASYNC_CHAT_META_PREFIX.length);
323	      const raw = await AsyncStorage.getItem(key);
324	      if (!raw) continue;
325	      let parsed: unknown;
326	      try {
327	        parsed = JSON.parse(raw);
328	      } catch {
329	        continue;
330	      }
331	      if (!Array.isArray(parsed)) continue;
332	      await writeMessages(db, chatId, parsed as ChatMessage[]);
333	    }
334	
335	    await db.runAsync(
336	      'INSERT INTO migration_meta (key, value) VALUES (?, ?) ON CONFLICT(key) DO UPDATE SET value = excluded.value',
337	      MIGRATION_FLAG_KEY,
338	      '1'
339	    );
340	  });
341	}
342	
343	/** Ensures the one-time AsyncStorage import has completed. Idempotent. */
344	async function ensureMigrated(db: Database): Promise<void> {
345	  if (migrationDone) return;
346	  try {
347	    await runAsyncStorageMigration(db);
348	  } catch (error) {
349	    // Don't let a migration failure block reads — SQLite is still authoritative
350	    // for anything already imported. We'll retry on the next launch.
351	    console.warn('[chat-repository] AsyncStorage migration failed:', error);
352	  }
353	  migrationDone = true;
354	}
