358	async function loadActiveRuns(
359	  db: Database,
360	  chatIds: string[]
361	): Promise<Map<string, ActiveChatRun>> {
362	  const out = new Map<string, ActiveChatRun>();
363	  if (chatIds.length === 0) return out;
364	  const placeholders = chatIds.map(() => '?').join(',');
365	  const rows = await db.getAllAsync<ActiveRunRow>(
366	    `SELECT * FROM active_runs WHERE chat_id IN (${placeholders})`,
367	    ...chatIds
368	  );
369	  for (const row of rows) {
370	    out.set(row.chat_id, rowToActiveRun(row));
371	  }
372	  return out;
373	}
