484	   * provider, workingDirectory, isClosed, lastSessionComplete, customName,
485	   * currentServiceName). Undefined fields are left untouched.
486	   */
487	  async patch(
488	    chatId: string,
489	    fields: Partial<
490	      Pick<
491	        PersistedChat,
492	        | 'lastUsed'
493	        | 'firstMessagePreview'
494	        | 'provider'
495	        | 'workingDirectory'
496	        | 'isClosed'
497	        | 'lastSessionComplete'
498	        | 'customName'
499	        | 'currentServiceName'
500	      >
501	    >
