504	    await ensureMigrated(db);
505	    const assignments: string[] = [];
506	    const params: (string | number | null)[] = [];
507	    const map: Array<[keyof typeof fields, string]> = [
508	      ['lastUsed', 'last_used'],
509	      ['firstMessagePreview', 'first_message_preview'],
510	      ['provider', 'provider'],
511	      ['workingDirectory', 'working_directory'],
512	      ['isClosed', 'is_closed'],
513	      ['lastSessionComplete', 'last_session_complete'],
