515	      ['currentServiceName', 'current_service_name'],
516	    ];
517	    for (const [field, column] of map) {
518	      const value = fields[field];
519	      if (value === undefined) continue;
520	      assignments.push(`${column} = ?`);
521	      if (field === 'isClosed' || field === 'lastSessionComplete') {
522	        params.push(value ? 1 : 0);
523	      } else if (value === null) {
524	        params.push(null);
525	      } else {
