function openTranscriptPaths() {
  const open = new Set();
  let pids;
  try { pids = fs.readdirSync('/proc'); } catch { return open; }
  for (const pid of pids) {
    if (!/^\d+$/.test(pid)) continue;
    let fds;
    try { fds = fs.readdirSync('/proc/' + pid + '/fd'); } catch { continue; }
    for (const f of fds) {
      let target;
      try { target = fs.readlinkSync('/proc/' + pid + '/fd/' + f); } catch { continue; }
      if (target.endsWith('.jsonl')) open.add(target);
    }
  }
  return open;
}

const open = openTranscriptPaths();
console.log('detected our file open:', open.has(fp));
console.log('total .jsonl fds seen:', open.size);
fs.closeSync(fd);
fs.rmSync(dir, { recursive: true, force: true });
