const fs = require('fs'), os = require('os'), path = require('path');
const { execFileSync } = require('child_process');

const WT = '/home/sprite/project/sprites-rn-manager-resume-sessions';

function extractListScript(file) {
  const src = fs.readFileSync(file, 'utf8');
  const m = src.match(/const LIST_SCRIPT = String\.raw`([\s\S]*?)`;/);
  if (!m) throw new Error('LIST_SCRIPT not found in ' + file);
  return m[1];
}

function runScript(script, home) {
  const tmp = path.join(os.tmpdir(), 'ls-' + Math.random().toString(36).slice(2) + '.js');
  fs.writeFileSync(tmp, script);
  const out = execFileSync('node', [tmp], { env: { ...process.env, HOME: home }, encoding: 'utf8' });
  fs.rmSync(tmp, { force: true });
  const s = out.indexOf('@@WISP@@'); const e = out.indexOf('@@WISP@@', s + 8);
  return JSON.parse(out.slice(s + 8, e));
}

function setMtime(fp, ageMs) {
  const t = (Date.now() - ageMs) / 1000;
  fs.utimesSync(fp, t, t);
}

// ---- Claude ----
{
  const home = fs.mkdtempSync(path.join(os.tmpdir(), 'claude-home-'));
  const proj = path.join(home, '.claude', 'projects', '-home-sprite-proj');
  fs.mkdirSync(proj, { recursive: true });
  const liveId = '11111111-aaaa-4bbb-8ccc-000000000001';
  const deadId = '22222222-aaaa-4bbb-8ccc-000000000002';
  const liveFp = path.join(proj, liveId + '.jsonl');
  const deadFp = path.join(proj, deadId + '.jsonl');
  const line = JSON.stringify({ type: 'user', cwd: '/home/sprite/proj', timestamp: new Date().toISOString(), message: { content: 'hello from PC' } }) + '\n';
  fs.writeFileSync(liveFp, line);
  fs.writeFileSync(deadFp, line);
  setMtime(deadFp, 10 * 60 * 1000); // 10 min old → not live by mtime
  setMtime(liveFp, 10 * 60 * 1000); // old too, but we hold it open → live via /proc
  const fd = fs.openSync(liveFp, 'r'); // simulate a running claude holding it open
  const res = runScript(extractListScript(path.join(WT, 'src/services/claude-sessions.ts')), home);
  fs.closeSync(fd);
  const byId = Object.fromEntries(res.map((r) => [r.id, r]));
  console.log('CLAUDE live(open-fd, old mtime):', byId[liveId] && byId[liveId].live, '(expect true)');
  console.log('CLAUDE live(stale):', byId[deadId] && byId[deadId].live, '(expect false)');
  console.log('CLAUDE cwd/preview ok:', byId[liveId] && byId[liveId].cwd === '/home/sprite/proj' && byId[liveId].preview === 'hello from PC');
  fs.rmSync(home, { recursive: true, force: true });
}

// ---- Codex ----
{
  const home = fs.mkdtempSync(path.join(os.tmpdir(), 'codex-home-'));
  const day = path.join(home, '.codex', 'sessions', '2026', '07', '04');
  fs.mkdirSync(day, { recursive: true });
  const liveId = '33333333-aaaa-4bbb-8ccc-000000000003';
  const deadId = '44444444-aaaa-4bbb-8ccc-000000000004';
  const liveName = 'rollout-2026-07-04T10-00-00-' + liveId + '.jsonl';
  const deadName = 'rollout-2026-07-04T09-00-00-' + deadId + '.jsonl';
  const liveFp = path.join(day, liveName);
  const deadFp = path.join(day, deadName);
  const l1 = JSON.stringify({ type: 'event_msg', timestamp: new Date().toISOString(), payload: { type: 'user_message', message: 'codex hi', cwd: '/root' } }) + '\n';
  fs.writeFileSync(liveFp, l1);
  fs.writeFileSync(deadFp, l1);
  setMtime(deadFp, 10 * 60 * 1000);
  setMtime(liveFp, 10 * 60 * 1000);
  const fd = fs.openSync(liveFp, 'r');
  const res = runScript(extractListScript(path.join(WT, 'src/services/codex-sessions.ts')), home);
  fs.closeSync(fd);
  const byId = Object.fromEntries(res.map((r) => [r.id, r]));
  console.log('CODEX live(open-fd, old mtime):', byId[liveId] && byId[liveId].live, '(expect true)');
  console.log('CODEX live(stale):', byId[deadId] && byId[deadId].live, '(expect false)');
  console.log('CODEX id/preview ok:', byId[liveId] && byId[liveId].preview === 'codex hi');
  fs.rmSync(home, { recursive: true, force: true });
}
EOF
