cat > /tmp/claude-1001/-home-sprite-project/1bd06bcd-1aa0-49a0-ab9f-6f3f2f0a86ef/scratchpad/merge-logic.js <<'EOF'
// Mirror the dedupe + interleave logic from sprite/[name].tsx + ChatList.tsx.
function unlinked(chatList, remoteSessions) {
  const linked = new Set();
  for (const c of chatList) {
    if (c.claudeSessionId) linked.add(c.claudeSessionId);
    if (c.codexSessionId) linked.add(c.codexSessionId);
  }
  return remoteSessions.filter((s) => !linked.has(s.id));
}
function mergeRows(chats, remote) {
  return [
    ...chats.map((chat) => ({ kind: 'local', label: chat.id, t: chat.lastUsed })),
    ...remote.map((s) => ({ kind: 'remote', label: s.id, t: s.modified })),
  ].sort((a, b) => b.t - a.t);
}

const chats = [
  { id: 'phone-1', lastUsed: 5000, claudeSessionId: 'S-linked' }, // linked to a remote
  { id: 'phone-2', lastUsed: 1000 },                              // fresh, no session yet
];
const remote = [
  { id: 'S-linked', modified: 6000, provider: 'claude' }, // should be deduped out
  { id: 'S-pc-new', modified: 9000, provider: 'codex' },  // computer, newest → top
  { id: 'S-pc-old', modified: 2000, provider: 'claude' }, // computer, older
];

const u = unlinked(chats, remote);
console.log('deduped ids:', u.map((s) => s.id).join(',') , '(expect S-pc-new,S-pc-old)');
const rows = mergeRows(chats, u);
console.log('interleaved order:', rows.map((r) => `${r.label}@${r.t}`).join(' > '));
console.log('expected order   : S-pc-new@9000 > phone-1@5000 > S-pc-old@2000 > phone-2@1000');
const ok = rows.map((r) => r.label).join(',') === 'S-pc-new,phone-1,S-pc-old,phone-2'
  && u.length === 2 && !u.find((s) => s.id === 'S-linked');
console.log('PASS:', ok);
EOF
